// Content with portions generated by generative AI platform
package org.eclipse.kura.linux.clock;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import org.eclipse.kura.KuraErrorCode;
import org.eclipse.kura.KuraException;
import org.junit.jupiter.api.Test;

class JavaNtpClockSyncProviderTest {

    private final AtomicReference<Runnable> tick = new AtomicReference<>();
    private final ScheduledExecutorService scheduler = mock(ScheduledExecutorService.class);
    private final ScheduledFuture<?> future = mock(ScheduledFuture.class);

    private void start(JavaNtpClockSyncProvider provider) throws KuraException {
        Map<String, Object> properties = new HashMap<>();
        properties.put("enabled", true);
        properties.put("clock.provider", "java-ntp");
        properties.put("clock.ntp.host", "localhost");
        properties.put("clock.ntp.port", 123);
        properties.put("clock.ntp.timeout", 100);
        properties.put("clock.ntp.retry.interval", 1);
        properties.put("clock.ntp.refresh-interval", 1);
        properties.put("clock.ntp.max-retry", 1);
        doAnswer(invocation -> {
            this.tick.set(invocation.getArgument(0));
            return this.future;
        }).when(this.scheduler).scheduleAtFixedRate(any(Runnable.class), eq(0L), eq(1L), eq(TimeUnit.SECONDS));
        provider.init(new ClockServiceConfig(properties), this.scheduler, null);
        provider.start();
        assertNotNull(this.tick.get());
    }

    private List<Runnable> startSingleSync(JavaNtpClockSyncProvider provider) throws KuraException {
        List<Runnable> submissions = new CopyOnWriteArrayList<>();
        doAnswer(invocation -> {
            submissions.add(invocation.getArgument(0));
            return this.future;
        }).when(this.scheduler).schedule(any(Runnable.class), eq(1L), eq(TimeUnit.SECONDS));
        provider.init(new ClockServiceConfig(Map.of("clock.ntp.refresh-interval", 0)), this.scheduler, null);
        provider.start();
        return submissions;
    }

    @Test
    void lateSingleSyncFailureCannotRestartAStoppedProvider() throws Exception {
        assertNoLateRetry(false);
    }

    @Test
    void lateSingleSyncFailureCannotJoinANewStart() throws Exception {
        assertNoLateRetry(true);
    }

    private void assertNoLateRetry(boolean restart) throws Exception {
        var started = new CompletableFuture<Void>();
        var release = new CompletableFuture<Void>();
        JavaNtpClockSyncProvider provider = new JavaNtpClockSyncProvider() {
            @Override
            protected boolean syncClock() throws KuraException {
                started.complete(null);
                release.join();
                throw new KuraException(KuraErrorCode.CONNECTION_FAILED);
            }
        };
        List<Runnable> submissions = startSingleSync(provider);
        try (var worker = Executors.newVirtualThreadPerTaskExecutor()) {
            var running = worker.submit(submissions.getFirst());
            try {
                started.get(5, TimeUnit.SECONDS);
                provider.stop();
                if (restart) {
                    provider.start();
                }
            } finally {
                release.complete(null);
            }
            running.get(5, TimeUnit.SECONDS);
            assertEquals(restart ? 2 : 1, submissions.size());
        }
    }

    @Test
    void currentSingleSyncRetriesAnExceptionAndFinishesOnSuccess() throws KuraException {
        var attempts = new AtomicInteger();
        JavaNtpClockSyncProvider provider = new JavaNtpClockSyncProvider() {
            @Override
            protected boolean syncClock() throws KuraException {
                if (attempts.incrementAndGet() == 1) {
                    throw new KuraException(KuraErrorCode.CONNECTION_FAILED);
                }
                return true;
            }
        };
        List<Runnable> submissions = startSingleSync(provider);
        submissions.getFirst().run();
        assertEquals(2, submissions.size());
        submissions.get(1).run();
        assertEquals(2, attempts.get());
        assertEquals(2, submissions.size());
    }

    @Test
    void testStartFail() throws KuraException {
        JavaNtpClockSyncProvider provider = new JavaNtpClockSyncProvider() {
            @Override protected boolean syncClock() { return false; }
        };
        start(provider);
        this.tick.get().run();
        assertTrue(provider.isSynced, "Exhausted retry attempts pause syncing until the refresh period");
        assertEquals(1, provider.numRetry);
        this.tick.get().run();
        assertEquals(1, provider.syncCount);
        assertEquals(0, provider.numRetry);
        assertFalse(provider.isSynced);
        provider.stop();
        verify(this.future).cancel(true);
    }

    @Test
    void testStart() throws KuraException {
        JavaNtpClockSyncProvider provider = new JavaNtpClockSyncProvider() {
            @Override protected boolean syncClock() { return true; }
        };
        start(provider);
        this.tick.get().run();
        assertTrue(provider.isSynced);
        assertEquals(0, provider.syncCount);
        assertEquals(0, provider.numRetry);
        provider.stop();
        verify(this.future).cancel(true);
    }

    @Test
    void testStartSynchException() throws KuraException {
        JavaNtpClockSyncProvider provider = new JavaNtpClockSyncProvider() {
            @Override protected boolean syncClock() throws KuraException {
                throw new KuraException(KuraErrorCode.CONFIGURATION_ERROR, "test");
            }
        };
        start(provider);
        this.tick.get().run();
        assertEquals(0, provider.syncCount);
        assertEquals(1, provider.numRetry);
        assertTrue(provider.isSynced);
        provider.stop();
        verify(this.future).cancel(true);
    }
}
